_ui_on_key = Ui.on_key

@patch
def on_key(self:Ui, k):
    if (k.name == 'ctrl+c' and self.mode != 'python' and self.ask is None
            and (self.turn is not None or self._stop_count)):
        self.buf.clear()
        return self.stop()
    return _ui_on_key(self, k)

